using System.Data;
using System.Data.OleDb;
using System.Runtime.InteropServices;
using ElevatorSystem.Models;

namespace ElevatorSystem.Data;

/// <summary>
/// The only class that talks to the MS Access database. Every other class goes through it, so
/// no database code is repeated anywhere else.
/// <para>
/// Uses the disconnected model: rows are added to a DataTable inside a DataSet and saved with
/// <see cref="OleDbDataAdapter.Update(DataSet, string)"/>, with the INSERT command generated by
/// <see cref="OleDbCommandBuilder"/>. ExecuteNonQuery is never used for inserts.
/// </para>
/// <para>
/// Each public method catches every failure and throws a <see cref="DataAccessException"/> whose message
/// can be shown to the user. These methods do blocking I/O, so callers run them on a BackgroundWorker.
/// </para>
/// </summary>
public sealed class ElevatorLogRepository
{
    public const string TableName = "ElevatorLog";
    public const string DatabaseFileName = "ElevatorLog.accdb";

    private const string SelectColumns = "[Id], [EventTime], [ElevatorId], [Floor], [Status]";
    private const int StatusMaxLength = 255;

    public ElevatorLogRepository()
    {
        // Relative to the executable's folder (bin\...\Data\ElevatorLog.accdb). No absolute paths.
        DataFolder = Path.Combine(Application.StartupPath, "Data");
        DatabasePath = Path.Combine(DataFolder, DatabaseFileName);
        // Kept minimal: ADOX Catalog.Create rejects extra keywords such as "Persist Security Info".
        ConnectionString = $"Provider=Microsoft.ACE.OLEDB.12.0;Data Source={DatabasePath};";
    }

    public string DataFolder { get; }
    public string DatabasePath { get; }
    public string ConnectionString { get; }

    /// <summary>Path relative to the application folder, for status messages.</summary>
    public string DisplayPath => Path.Combine("Data", DatabaseFileName);

    /// <summary>
    /// Makes sure the database file and the log table exist, creating them with ADOX when missing.
    /// Returns true if anything had to be created.
    /// </summary>
    public bool EnsureDatabase()
    {
        try
        {
            bool created = false;
            Directory.CreateDirectory(DataFolder);

            if (!File.Exists(DatabasePath))
            {
                CreateDatabaseFile();
                created = true;
            }

            if (!LogTableExists())
            {
                CreateLogTable();
                created = true;
            }

            return created;
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "prepare the log database");
        }
    }

    /// <summary>Saves a batch of log entries with DataAdapter.Update (disconnected model).</summary>
    public void InsertLogs(IReadOnlyCollection<LogEntry> entries)
    {
        if (entries.Count == 0)
        {
            return;
        }

        try
        {
            // The file may have been deleted while the program was running: recreate it, don't lose the log.
            if (!File.Exists(DatabasePath))
            {
                EnsureDatabase();
            }

            using var connection = new OleDbConnection(ConnectionString);

            // "WHERE 1 = 0" fetches only the schema; no existing rows are loaded just to append new ones.
            using var adapter = new OleDbDataAdapter($"SELECT {SelectColumns} FROM [{TableName}] WHERE 1 = 0", connection);
            using var builder = new OleDbCommandBuilder(adapter) { QuotePrefix = "[", QuoteSuffix = "]" };

            var dataSet = new DataSet("ElevatorLogs");
            adapter.FillSchema(dataSet, SchemaType.Source, TableName);
            DataTable table = dataSet.Tables[TableName]!;

            foreach (LogEntry entry in entries)
            {
                DataRow row = table.NewRow();
                // Id is an AutoNumber: the command builder leaves it out of the INSERT.
                row["EventTime"] = TruncateToSeconds(entry.EventTime);
                row["ElevatorId"] = entry.ElevatorId;
                row["Floor"] = entry.Floor;
                row["Status"] = entry.Status.Length > StatusMaxLength ? entry.Status[..StatusMaxLength] : entry.Status;
                table.Rows.Add(row);
            }

            adapter.InsertCommand = builder.GetInsertCommand();
            adapter.Update(dataSet, TableName);
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "save the operation log");
        }
    }

    /// <summary>Loads the whole log, newest first, into a disconnected DataTable for display.</summary>
    public DataTable LoadLogs()
    {
        try
        {
            if (!File.Exists(DatabasePath))
            {
                EnsureDatabase();
            }

            using var connection = new OleDbConnection(ConnectionString);
            using var adapter = new OleDbDataAdapter($"SELECT {SelectColumns} FROM [{TableName}] ORDER BY [Id] DESC", connection);

            var dataSet = new DataSet("ElevatorLogs");
            adapter.Fill(dataSet, TableName);
            return dataSet.Tables[TableName]!;
        }
        catch (Exception ex) when (ex is not DataAccessException)
        {
            throw Translate(ex, "load the operation log");
        }
    }

    private void CreateDatabaseFile()
    {
        var catalog = new ADOX.Catalog();
        try
        {
            // Creates an empty .accdb; Create returns the ADODB connection it opened, which must be closed
            // or the file stays locked.
            object connection = catalog.Create(ConnectionString);
            CloseAdoConnection(connection);
        }
        finally
        {
            Marshal.FinalReleaseComObject(catalog);
        }
    }

    private void CreateLogTable()
    {
        var catalog = new ADOX.Catalog();
        try
        {
            catalog.let_ActiveConnection(ConnectionString);

            var table = new ADOX.Table { Name = TableName };
            table.ParentCatalog = catalog;

            // AutoNumber = Long Integer with the provider's AutoIncrement property (needs ParentCatalog set first).
            var id = new ADOX.Column { Name = "Id", Type = ADOX.DataTypeEnum.adInteger };
            id.ParentCatalog = catalog;
            id.Properties["AutoIncrement"].Value = true;

            table.Columns.Append(id);
            table.Columns.Append("EventTime", ADOX.DataTypeEnum.adDate);
            table.Columns.Append("ElevatorId", ADOX.DataTypeEnum.adInteger);
            table.Columns.Append("Floor", ADOX.DataTypeEnum.adInteger);
            table.Columns.Append("Status", ADOX.DataTypeEnum.adVarWChar, StatusMaxLength);
            table.Keys.Append("PK_" + TableName, ADOX.KeyTypeEnum.adKeyPrimary, "Id");

            catalog.Tables.Append(table);
            CloseAdoConnection(catalog.ActiveConnection);
        }
        finally
        {
            Marshal.FinalReleaseComObject(catalog);
        }
    }

    private bool LogTableExists()
    {
        using var connection = new OleDbConnection(ConnectionString);
        connection.Open();

        // Restrictions: catalog, schema, table name, table type.
        DataTable tables = connection.GetOleDbSchemaTable(OleDbSchemaGuid.Tables, new object?[] { null, null, TableName, "TABLE" })!;
        return tables.Rows.Count > 0;
    }

    /// <summary>Closes the ADODB.Connection object that ADOX hands back (late bound, ADODB is not referenced).</summary>
    private static void CloseAdoConnection(object? connection)
    {
        if (connection is null)
        {
            return;
        }

        try
        {
            ((dynamic)connection).Close();
        }
        catch (COMException)
        {
            // Already closed: nothing to do.
        }
        finally
        {
            Marshal.FinalReleaseComObject(connection);
        }
    }

    /// <summary>
    /// Access rejects OLE DB timestamp parameters with fractional seconds ("Data type mismatch"), so
    /// times are stored to the second. Entries keep their order through the AutoNumber Id.
    /// </summary>
    private static DateTime TruncateToSeconds(DateTime value) =>
        new(value.Ticks - value.Ticks % TimeSpan.TicksPerSecond, value.Kind);

    /// <summary>Maps low-level exceptions to messages a user can act on.</summary>
    private DataAccessException Translate(Exception ex, string action)
    {
        string message = ex.Message;
        string reason;

        if (ex is InvalidOperationException && message.Contains("not registered", StringComparison.OrdinalIgnoreCase))
        {
            reason = "The Microsoft Access Database Engine (64-bit ACE OLE DB provider) is not installed on this computer.";
        }
        else if (ex is OleDbException && (message.Contains("already in use", StringComparison.OrdinalIgnoreCase)
                 || message.Contains("exclusively", StringComparison.OrdinalIgnoreCase)
                 || message.Contains("locked", StringComparison.OrdinalIgnoreCase)
                 || message.Contains("placed in a state", StringComparison.OrdinalIgnoreCase)))
        {
            reason = $"The database file '{DisplayPath}' is locked by another program. Close it (for example in MS Access) and try again.";
        }
        else if (message.Contains("Could not find file", StringComparison.OrdinalIgnoreCase))
        {
            reason = $"The database file '{DisplayPath}' could not be found.";
        }
        else if (message.Contains("Unrecognized database format", StringComparison.OrdinalIgnoreCase))
        {
            reason = $"The database file '{DisplayPath}' is damaged or is not an Access database. Delete it and restart the program to create a new one.";
        }
        else if (ex is UnauthorizedAccessException)
        {
            reason = $"No permission to access '{DisplayPath}'. Check that the Data folder is not read-only.";
        }
        else if (ex is IOException)
        {
            reason = $"The file '{DisplayPath}' could not be accessed: {message}";
        }
        else if (ex is OleDbException || ex is COMException)
        {
            reason = $"The database reported an error: {message}";
        }
        else
        {
            reason = $"Unexpected error: {message}";
        }

        return new DataAccessException($"Could not {action}. {reason}", ex);
    }
}
